"""Anthropic / pydantic-ai compatibility shims for Copilot v2.

TODO(SWI-1241): Remove once pydantic-ai-slim ships a fix for the
``UserLocation`` -> ``BetaUserLocationParam`` rename in anthropic >=0.100.
"""

from __future__ import annotations

import structlog

structlogger = structlog.get_logger()


def apply_anthropic_compat_shims() -> None:
    """Patch anthropic type aliases that pydantic-ai still imports under old names."""
    try:
        from anthropic.types.beta import beta_web_search_tool_20250305_param as _bwst

        # Access both names dynamically: depending on the installed anthropic
        # version one or the other may be absent, and going through
        # getattr/setattr keeps mypy from flagging attributes it can't see (which
        # would otherwise need an env-dependent ``type: ignore``).
        renamed = getattr(_bwst, "BetaUserLocationParam", None)
        if renamed is not None and not hasattr(_bwst, "UserLocation"):
            setattr(_bwst, "UserLocation", renamed)
    except Exception as exc:
        # Best-effort shim: anthropic may be absent or may have changed its type
        # layout again. Log at debug so a future breakage leaves a breadcrumb
        # rather than failing opaquely downstream.
        structlogger.debug("copilot_v2.anthropic_compat.shim_skipped", error=str(exc))
